package com.quickmanager.controller;

import com.quickmanager.debug.Address;
import com.quickmanager.model.TaiKhoan;
import com.quickmanager.service.SessionService;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.layout.AnchorPane;
import javafx.scene.control.Label;

import java.util.Objects;

public class DashBoardController {
    @FXML
    private AnchorPane contentPane;

    @FXML
    private Label accountLabel;

    @FXML
    private Label roleLabel;

    @FXML
    public void initialize() {
        TaiKhoan tk = SessionService.getUser();
        accountLabel.setText(tk.getTenDangNhap());
        roleLabel.setText(tk.getVaiTro());
        setPage("home.fxml");
    }

    public void setPage(String path) {
        try {
            Parent children = FXMLLoader.load(Objects.requireNonNull(getClass().getResource("/view/"+path)));
            contentPane.getChildren().setAll(children);
            AnchorPane.setTopAnchor(children, 0.0);
            AnchorPane.setRightAnchor(children, 0.0);
            AnchorPane.setBottomAnchor(children, 0.0);
            AnchorPane.setLeftAnchor(children, 0.0);
        }catch (Exception e){
            System.out.println("Lỗi: " + e.getMessage());
            Address.printAddress();
        }
    }
    public void switchHomePage() { setPage("home.fxml"); }
    public void switchSellPage() {setPage("sell.fxml");}
    public void switchImportPage() { setPage("import.fxml"); }
    public void switchInvoicePage() { setPage("invoice.fxml"); }
    public void switchProductPage() { setPage("product.fxml"); }
    public void switchEmployeePage() { setPage("employee.fxml"); }
    public void switchStatisticsPage() { setPage("statistics.fxml"); }
}

package com.quickmanager.controller;

import com.quickmanager.debug.Address;
import com.quickmanager.model.TaiKhoan;
import com.quickmanager.service.SessionService;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.input.MouseEvent;
import javafx.scene.layout.AnchorPane;
import javafx.scene.control.Label;
import javafx.stage.Stage;

import java.util.Objects;

public class DashBoardController {
    @FXML
    private AnchorPane contentPane;

    @FXML
    private Label accountLabel;

    @FXML
    private Label roleLabel;

    private double dragOffsetX;
    private double dragOffsetY;

    @FXML
    public void initialize() {
        TaiKhoan tk = SessionService.getUser();
        accountLabel.setText(tk.getTenDangNhap());
        roleLabel.setText(tk.getVaiTro());
        setPage("home.fxml");
    }

    public void setPage(String path) {
        try {
            Parent children = FXMLLoader.load(Objects.requireNonNull(getClass().getResource("/view/"+path)));
            contentPane.getChildren().setAll(children);
            AnchorPane.setTopAnchor(children, 0.0);
            AnchorPane.setRightAnchor(children, 0.0);
            AnchorPane.setBottomAnchor(children, 0.0);
            AnchorPane.setLeftAnchor(children, 0.0);
        }catch (Exception e){
            System.out.println("Lỗi: " + e.getMessage());
            Address.printAddress();
        }
    }
    public void switchHomePage() { setPage("home.fxml"); }
    public void switchSellPage() {setPage("sell.fxml");}
    public void switchImportPage() { setPage("import.fxml"); }
    public void switchInvoicePage() { setPage("invoice.fxml"); }
    public void switchProductPage() { setPage("product.fxml"); }
    public void switchEmployeePage() { setPage("employee.fxml"); }
    public void switchStatisticsPage() { setPage("statistics.fxml"); }

    @FXML
    public void handleMinimize() {
        Stage stage = getStage();
        if (stage != null) {
            stage.setIconified(true);
        }
    }

    @FXML
    public void handleMaximize() {
        Stage stage = getStage();
        if (stage != null) {
            stage.setMaximized(!stage.isMaximized());
        }
    }

    @FXML
    public void handleClose() {
        Stage stage = getStage();
        if (stage != null) {
            stage.close();
        }
    }

    @FXML
    public void handleHeaderPressed(MouseEvent event) {
        Stage stage = getStage();
        if (stage != null) {
            dragOffsetX = event.getSceneX();
            dragOffsetY = event.getSceneY();
        }
    }

    @FXML
    public void handleHeaderDragged(MouseEvent event) {
        Stage stage = getStage();
        if (stage != null && !stage.isMaximized()) {
            stage.setX(event.getScreenX() - dragOffsetX);
            stage.setY(event.getScreenY() - dragOffsetY);
        }
    }

    private Stage getStage() {
        if (contentPane == null || contentPane.getScene() == null || !(contentPane.getScene().getWindow() instanceof Stage)) {
            return null;
        }
        return (Stage) contentPane.getScene().getWindow();
    }
}

package com.quickmanager.model;

public class CanhBaoTonKho {
    private int maSanPham;
    private String tenSanPham;
    private int tonKho;
    private int mucToiThieu;
    private String trangThai;

    public CanhBaoTonKho(int maSanPham, String tenSanPham, int tonKho, int mucToiThieu, String trangThai) {
        this.maSanPham = maSanPham;
        this.tenSanPham = tenSanPham;
        this.tonKho = tonKho;
        this.mucToiThieu = mucToiThieu;
        this.trangThai = trangThai;
    }

    public int getMaSanPham() { return maSanPham; }
    public String getTenSanPham() { return tenSanPham; }
    public int getTonKho() { return tonKho; }
    public int getMucToiThieu() { return mucToiThieu; }
    public String getTrangThai() { return trangThai; }
}

package com.quickmanager.model;

import java.math.BigDecimal;
import java.time.LocalDate;

public class DoanhThuNgay {
    private LocalDate ngay;
    private int soHoaDon;
    private BigDecimal doanhThu;

    public DoanhThuNgay(LocalDate ngay, int soHoaDon, BigDecimal doanhThu) {
        this.ngay = ngay;
        this.soHoaDon = soHoaDon;
        this.doanhThu = doanhThu;
    }

    public LocalDate getNgay() { return ngay; }
    public int getSoHoaDon() { return soHoaDon; }
    public BigDecimal getDoanhThu() { return doanhThu; }
}

package com.quickmanager.model;

import java.math.BigDecimal;

public class TopSanPham {
	private String tenSanPham;
	private int soLuong;
	private BigDecimal doanhThu;

	public TopSanPham(String tenSanPham, int soLuong, BigDecimal doanhThu) {
		this.tenSanPham = tenSanPham;
		this.soLuong = soLuong;
		this.doanhThu = doanhThu;
	}

	public String getTenSanPham() { return tenSanPham; }
	public int getSoLuong() { return soLuong; }
	public BigDecimal getDoanhThu() { return doanhThu; }
}

.root {
    /* Nen tong cua ung dung (background chinh) */
    -qm-bg-app: #151515;
    /* Nen panel/card (khoi noi dung) */
    -qm-bg-pane: #1e293b;
    /* Nen control noi bat hon (input, field) */
    -qm-bg-elevated: #334155;
    /* Nen dau bang/table header */
    -qm-bg-control: #1e1e1e;
    /* Nen dong table */
    -qm-bg-row: #262626;
    /* Nen dong xen ke table */
    -qm-bg-row-alt: #2e2e2e;
    /* Nen dong duoc chon */
    -qm-bg-selected: #334155;

    /* Mau vien chinh */
    -qm-border: #263241;
    /* Mau vien mem (phan tach nhe) */
    -qm-border-soft: #223041;
    /* Mau vien input/control */
    -qm-border-light: #314257;

    /* Mau chu chinh */
    -qm-text-primary: #f1f5f9;
    /* Mau chu phu (noi dung thu cap) */
    -qm-text-secondary: #dbe5f0;
    /* Mau chu nhan/phu de */
    -qm-text-muted: #9fb0c2;
    /* Mau chu mo (hint, placeholder nhat) */
    -qm-text-subtle: #7f92a7;
    /* Mau chu rieng cho sidebar */
    -qm-text-sidebar: #9fb0c3;
    /* Mau placeholder trong o nhap */
    -qm-text-placeholder: #7f92a7;

    /* Mau button/chuc nang chinh (xanh duong) */
    -qm-accent-primary: #2563eb;
    /* Mau canh bao/huy (do) */
    -qm-accent-red: #dc2626;
    /* Mau thanh cong/xac nhan (xanh la) */
    -qm-accent-green: #16a34a;
    /* Mau xanh duong mo rong (giu de tai su dung) */
    -qm-accent-blue: #2563eb;
    /* Mau tong tien thanh cong */
    -qm-accent-success: #10b981;
    /* Mau canh bao nhe (cam) */
    -qm-accent-warning: #f97316;
    /* Vien nhan panel trai */
    -qm-accent-left: #2563eb;
    /* Vien nhan panel phai */
    -qm-accent-right: #16a34a;
    /* Gradient nut menu - mau bat dau */
    -qm-gradient-menu-start: #1b9a88;
    /* Gradient nut menu - mau ket thuc */
    -qm-gradient-menu-end: #2f8cd8;

    /* Nen trang dang nhap */
    -qm-login-bg: #0f172a;
    /* Nen the dang nhap */
    -qm-login-card: rgba(250, 250, 250, 0.5);
    /* Mau tieu de dang nhap */
    -qm-login-title: #0f172a;
    /* Mau phu de dang nhap */
    -qm-login-subtitle: #64748b;
    /* Mau nhan tren form dang nhap */
    -qm-login-label: #1e293b;
    /* Mau vien o nhap trang dang nhap */
    -qm-login-input-border: #cbd5e1;
}

* {
    -fx-font-family: "Urbanist", "Arial", "Tahoma", sans-serif;
}

.login-pane {
    -fx-background-color: -qm-login-bg;
}

.login-card {
    -fx-background-color: -qm-login-card;
    -fx-background-radius: 18;
}

.title-label {
    -fx-text-fill: -qm-login-title;
    -fx-font-size: 22;
    -fx-font-weight: bold;
}

.subtitle-label {
    -fx-text-fill: -qm-login-subtitle;
    -fx-font-size: 12;
}

.field-label {
    -fx-font-size: 12;
    -fx-font-weight: bold;
    -fx-text-fill: -qm-login-label;
}

.input-field {
    -fx-background-radius: 10;
    -fx-border-radius: 10;
    -fx-border-color: -qm-login-input-border;
    -fx-padding: 10 12;
    -fx-font-size: 16;
}

.forgot-link {
    -fx-text-fill: -qm-accent-blue;
}

.status-label {
    -fx-text-fill: -qm-accent-red;
    -fx-font-size: 12;
}

.dashBoard,
.mainPane,
.qm-page {
    -fx-background-color: -qm-bg-app;
}

.sideBar {
    -fx-border-color: transparent -qm-border transparent transparent;
    -fx-border-width: 0 1 0 0;
}

.logo {
    -fx-text-fill: -qm-text-sidebar;
    -fx-font-size: 20;
    -fx-font-weight: 900;
}

.logoPane,
.header {
    -fx-border-color: transparent transparent -qm-border transparent;
    -fx-border-width: 0 0 1 0;
    -fx-padding: 0 24 0 24;
    -fx-background-color: -qm-bg-app;
}

.header-label {
    -fx-font-size: 16;
    -fx-font-weight: 700;
    -fx-text-fill: -qm-text-primary;
}

.header-search {
    -fx-pref-height: 38;
    -fx-min-width: 260;
}

.header-action-btn {
    -fx-pref-height: 38;
    -fx-padding: 0 14 0 14;
}

.sidebar-menu {
    -fx-padding: 22 0 22 0;
}

.menu-btn {
    -fx-max-width: Infinity;
    -fx-pref-height: 38;
    -fx-alignment: CENTER_LEFT;
    -fx-padding: 18 0 18 38;
    -fx-background-insets: 0 38 0 0;
    -fx-border-insets: 0;
    -fx-background-radius: 0 26 26 0;
    -fx-border-radius: 0 26 26 0;
    -fx-background-color: transparent;
    -fx-text-fill: -qm-text-sidebar;
    -fx-font-size: 16;
    -fx-font-weight: 500;
    -fx-cursor: hand;
}

.menu-btn:selected {
    -fx-background-color: linear-gradient(to right, -qm-gradient-menu-start, -qm-gradient-menu-end);
    -fx-background-radius: 0 26 26 0;
    -fx-text-fill: -qm-text-primary;
    -fx-font-weight: 500;
}

.btn,
.qm-btn {
    -fx-background-color: -qm-accent-primary;
    -fx-border-color: transparent;
    -fx-border-radius: 8;
    -fx-background-radius: 8;
    -fx-text-fill: -qm-text-primary;
    -fx-font-size: 16;
    -fx-font-weight: bold;
}

.btn:hover,
.qm-btn:hover {
    -fx-opacity: 0.92;
}

.btn:pressed,
.qm-btn:pressed {
    -fx-opacity: 0.82;
}

.btn:disabled,
.qm-btn:disabled {
    -fx-opacity: 0.7;
}

.btn-red {
    -fx-background-color: -qm-accent-red;
    -fx-text-fill: -qm-text-primary;
    -fx-font-weight: bold;
    -fx-background-radius: 8;
    -fx-font-size: 16;
}

.btn-green {
    -fx-background-color: -qm-accent-green;
    -fx-text-fill: -qm-text-primary;
    -fx-font-size: 16;
    -fx-font-weight: bold;
    -fx-background-radius: 8;
}

.btn-blue {
    -fx-background-color: -qm-accent-blue;
    -fx-text-fill: -qm-text-primary;
    -fx-font-weight: bold;
    -fx-background-radius: 8;
    -fx-font-size: 16;
    -fx-cursor: hand;
}

.titlePage {
    -fx-font-size: 22;
    -fx-text-fill: -qm-text-primary;
}

.dashboard-split > .split-pane-divider,
.qm-content > .split-pane-divider {
    -fx-background-color: transparent;
    -fx-padding: 0;
    -fx-border-width: 0;
}

.dashboard-split > .split-pane-divider > .vertical-grabber,
.qm-content > .split-pane-divider > .vertical-grabber {
    -fx-padding: 0;
    -fx-background-color: transparent;
}

.qm-topbar {
    -fx-padding: 14 16;
    -fx-border-color: transparent transparent -qm-border-soft transparent;
    -fx-border-width: 0 0 1 0;
}

.qm-page-title {
    -fx-text-fill: -qm-text-primary;
    -fx-font-size: 22;
    -fx-font-weight: 700;
}

.qm-label-muted {
    -fx-text-fill: -qm-text-muted;
}

.qm-content {
    -fx-padding: 12 16;
}

.qm-content,
.qm-content > .split-pane-content {
    -fx-background-color: -qm-bg-app;
}

.qm-page .split-pane > .split-pane-content {
    -fx-background-color: -qm-bg-app;
}

.qm-panel,
.qm-form {
    -fx-padding: 12;
    -fx-background-color: -qm-bg-pane;
    -fx-background-radius: 10;
    -fx-border-color: -qm-border-soft;
    -fx-border-radius: 10;
    -fx-border-width: 1;
}

.qm-panel-left {
    -fx-border-color: -qm-accent-left -qm-border-soft -qm-border-soft -qm-border-soft;
    -fx-border-width: 3 1 1 1;
}

.qm-panel-right {
    -fx-border-color: -qm-accent-right -qm-border-soft -qm-border-soft -qm-border-soft;
    -fx-border-width: 3 1 1 1;
}

.qm-section-title {
    -fx-text-fill: -qm-text-primary;
    -fx-font-size: 16;
    -fx-font-weight: 600;
}

.qm-table {
    -fx-background-color: -qm-bg-control;
    -fx-control-inner-background: -qm-bg-row;
    -fx-background-insets: 0;
    -fx-border-color: -qm-border-soft;
    -fx-border-radius: 8;
    -fx-background-radius: 8;
}

.qm-table .virtual-flow,
.qm-table .clipped-container,
.qm-table .corner,
.qm-table .placeholder {
    -fx-background-color: -qm-bg-row;
}

.qm-table .column-header-background,
.qm-table .filler,
.qm-table .column-header {
    -fx-background-color: -qm-bg-control;
}

.qm-table .column-header {
    -fx-border-color: transparent -qm-border-soft transparent transparent;
}

.qm-table .column-header .label {
    -fx-text-fill: -qm-text-secondary;
    -fx-font-weight: 600;
}

.qm-table .table-row-cell {
    -fx-background-color: -qm-bg-row;
    -fx-border-color: transparent transparent -qm-bg-elevated transparent;
}

.qm-table .table-row-cell:odd {
    -fx-background-color: -qm-bg-row-alt;
}

.qm-table .table-row-cell:selected {
    -fx-background-color: -qm-bg-selected;
}

.qm-table .table-cell {
    -fx-text-fill: -qm-text-secondary;
    -fx-border-color: transparent;
}

.qm-table .placeholder .label,
.qm-hint {
    -fx-text-fill: -qm-text-subtle;
}

.qm-hint {
    -fx-font-size: 12;
}

.qm-form {
    -fx-padding: 10;
    -fx-background-radius: 8;
    -fx-border-radius: 8;
}

.qm-value {
    -fx-text-fill: -qm-text-secondary;
}

.qm-total-label {
    -fx-text-fill: -qm-text-primary;
    -fx-font-weight: 700;
}

.qm-total-value {
    -fx-text-fill: -qm-accent-success;
    -fx-font-size: 16;
    -fx-font-weight: 700;
}

.qm-warning-value {
    -fx-text-fill: -qm-accent-warning;
    -fx-font-weight: 700;
}

.qm-input,
.qm-form .text-field {
    -fx-background-color: -qm-bg-elevated;
    -fx-background-radius: 8;
    -fx-border-radius: 8;
    -fx-border-color: -qm-border-light;
    -fx-text-fill: -qm-text-secondary;
    -fx-prompt-text-fill: -qm-text-placeholder;
}

.qm-input:focused,
.qm-form .text-field:focused {
    -fx-border-color: -qm-accent-primary;
}

.qm-combo,
.qm-page .combo-box,
.qm-page .date-picker {
    -fx-background-color: -qm-bg-elevated;
    -fx-background-radius: 8;
    -fx-border-radius: 8;
    -fx-border-color: -qm-border-light;
}

.qm-page .combo-box .list-cell,
.qm-page .date-picker .text-field {
    -fx-background-color: transparent;
    -fx-text-fill: -qm-text-secondary;
}

.qm-page .combo-box:focused,
.qm-page .date-picker:focused {
    -fx-border-color: -qm-accent-primary;
}


.qm-page .combo-box-popup .list-view,
.qm-page .date-picker-popup {
    -fx-background-color: -qm-bg-pane;
}

/* Chart theming to match app colors */
.chart {
    -fx-background-color: transparent;
    -fx-padding: 6 6 6 6;
}
.chart-title {
    -fx-text-fill: -qm-text-primary;
    -fx-font-weight: 600;
}
.chart-legend {
    -fx-background-color: transparent;
}
.chart-plot-background {
    -fx-background-color: -qm-bg-pane; /* panel background for charts */
    -fx-border-color: -qm-border-soft;
    -fx-border-width: 1;
}

/* Bar colors */
.chart-bar .default-color0.chart-bar { -fx-bar-fill: -qm-accent-primary; }
.chart-bar .default-color1.chart-bar { -fx-bar-fill: -qm-accent-right; }
.chart-bar .default-color2.chart-bar { -fx-bar-fill: -qm-accent-green; }
.chart-bar .default-color3.chart-bar { -fx-bar-fill: -qm-accent-warning; }

/* Line and area series */
.chart-series-line .chart-line-symbol { -fx-background-color: -qm-accent-primary, white; }
.chart-series-line .default-color0.chart-series-line { -fx-stroke: -qm-accent-primary; -fx-stroke-width: 2; }
.chart-series-area .default-color0.chart-series-area { -fx-fill: derive(-qm-accent-primary, 40%); }

/* Pie chart */
.chart-pie .chart-pie-label { -fx-text-fill: -qm-text-primary; }
.chart-pie .default-color0 { -fx-pie-color: -qm-accent-primary; }
.chart-pie .default-color1 { -fx-pie-color: -qm-accent-right; }
.chart-pie .default-color2 { -fx-pie-color: -qm-accent-green; }
.chart-pie .default-color3 { -fx-pie-color: -qm-accent-warning; }

/* Tooltip / labels */
.chart .chart-plot-background .axis-label, .chart .axis .tick-label { -fx-text-fill: -qm-text-secondary; }

.root {
    /* Nen tong cua ung dung (background chinh) */
    -qm-bg-app: #151515;
    /* Nen panel/card (khoi noi dung) */
    -qm-bg-pane: #1e293b;
    /* Nen control noi bat hon (input, field) */
    -qm-bg-elevated: #334155;
    /* Nen dau bang/table header */
